st GDP $114.2bn (2025)"]},{"headline":"Early signal: petroleum oils and oils from bituminous minerals, not containing biodiesel, not crude, not waste oils; preparations n.e.c, containing by weight 70% or more of petroleum oils or oils from bituminous minerals; not light oils and preparations","detail":"Not a headline product yet, but growing 347% a year. Categories that hold that rate tend to reprice the market before they show up in the top ten, which is the window where entry is cheapest.","angle":"timing","strength":"strong","evidence":["Minerals & energy: growing 347% a year since 2022, now 0.52% of exports at rank 12. Largest counterpart across all exports is United Arab Emirates. Growth is uneven, so treat the projection as directional."]}]','2026-09-06 10:18:32'),('res_08c58d8382f54aca9c0377','ent_cote-divoire','run_846af31cf50e4a579e044c','overview','{"year":2025,"export_usd":29432666115.651,"import_usd":19583421272.797,"balance_usd":9849244842.854,"total_trade_usd":49016087388.448,"export_yoy_pct":43.23258337151827,"import_yoy_pct":13.729467330908085,"export_concentration":0.22579593099202555,"export_chapter_shares":{"10":0.0005451803927293595,"11":0.00033056249487463244,"12":0.0003621367647470444,"13":0.0001138476010917251,"14":0.0005195650725936406,"15":0.010167564709807866,"16":0.0021935946519869983,"17":0.00037172539660564367,"18":0.4033513828085103,"19":0.001678769073411735,"20":0.0003259075664538881,"21":0.006250341728920274,"22":0.00023041024263157055,"23":0.001676000469756197,"24":0.0034378757383861664,"25":0.0012484507268428102,"26":0.005581656540678433,"27":0.12579595845820427,"28":0.0004038538575573112,"29":0.00004044026488539112,"30":0.00031269667595989705,"31":0.002676349518677339,"32":0.0005867418340610277,"33":0.012232006183178153,"34":0.004792321669018605,"35":0.00002577879289014409,"36":0.000021233123310830024,"37":0.000004269618712291835,"38":0.0016698817108815375,"39":0.009940863585323156,"40":0.11848833691352655,"41":0.000006333879413693